function findLHS(nums) {
  const count = new Map();
  for (const num of nums) {
    count.set(num, (count.get(num) || 0) + 1);
  }

  let best = 0;
  for (const [value, freq] of count) {
    if (count.has(value + 1)) {
      best = Math.max(best, freq + count.get(value + 1));
    }
  }
  return best;
}

