function findLHS(nums) {
  // For each element taken as the minimum, count everything equal to it or one larger.
  let best = 0;
  for (let i = 0; i < nums.length; i++) {
    let length = 0, hasBigger = false;
    for (let j = 0; j < nums.length; j++) {
      if (nums[j] === nums[i]) length++;
      else if (nums[j] === nums[i] + 1) { length++; hasBigger = true; }
    }
    if (hasBigger && length > best) best = length;
  }
  return best;
}

