function generate(rand, size) {
  const pick = m => Math.floor(rand() * m);
  const n = size === 'large' ? 1500 + pick(501) : 1 + pick(10);
  const style = pick(4);
  let base, span;
  if (style === 0) { base = -3; span = 7; }
  else if (style === 1) { base = 1e9 - 4; span = 5; }
  else if (style === 2) { base = -1e9; span = 5; }
  else { base = pick(2000) - 1000; span = size === 'large' ? 600 : 4; }
  const nums = Array.from({ length: n }, () => base + pick(span));
  if (size === 'large' && pick(3) === 0) {
    // Spread values far apart (all even), so only a few harmonious pairs exist.
    for (let i = 0; i < n; i++) nums[i] = 2 * (pick(1e6) - 5e5);
    for (let t = 0; t < 5; t++) nums[pick(n)] = nums[pick(n)] + 1;
  }
  return [nums];
}
